package app.relaydrop;

import android.app.*;
import android.content.*;
import android.database.Cursor;
import android.net.*;
import android.os.*;
import android.provider.DocumentsContract;
import org.json.*;
import java.io.*;
import java.net.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import javax.net.ssl.SSLException;

/** Download into private resumable cache, then publish one new SAF document and read it back. */
public final class ReceiveQueueService extends Service {
  static final String ENQUEUE="ENQUEUE",PAUSE="PAUSE",RESUME="RESUME",CANCEL="CANCEL",WAKE="WAKE";
  private static final int NOTICE=34;
  private static final long RESERVE=32L*1024*1024,MAX_FILE=20L*1024*1024*1024;
  private final ExecutorService commands=Executors.newSingleThreadExecutor();
  private final ExecutorService intake=Executors.newSingleThreadExecutor();
  private volatile long intakeEpoch;
  private volatile boolean pauseIntake;
  private final Object signal=new Object();
  private final java.util.concurrent.atomic.AtomicInteger pending=new java.util.concurrent.atomic.AtomicInteger();
  private ReceiveQueueStore store;
  private NotificationManager notifications;
  private PowerManager.WakeLock wake;
  private ConnectivityManager connectivity;
  private ConnectivityManager.NetworkCallback network;
  private volatile Thread worker;
  private volatile boolean destroyed;
  private volatile String currentId;
  private volatile HttpURLConnection connection;
  private volatile ShareTransport transport;
  private volatile long revision;
  private int lastStart;
  private long notified,journaled;
  private static final class SaveFailure extends IOException{SaveFailure(String text){super(text);}}
  static void control(Context c,String action,String id){Intent intent=new Intent(c,ReceiveQueueService.class).setAction(action);if(id!=null)intent.putExtra("id",id);c.startForegroundService(intent);}
  @Override public void onCreate(){super.onCreate();notifications=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);notifications.createNotificationChannel(new NotificationChannel("relay-saves","后台保存与最近文件",NotificationManager.IMPORTANCE_LOW));startForeground(NOTICE,notice("正在恢复后台保存…",0,0,false));try{store=ReceiveQueueStore.get(this);wake=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"RelayDrop:save");connectivity=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);network=new ConnectivityManager.NetworkCallback(){@Override public void onAvailable(Network n){if(destroyed)return;try{commands.execute(()->{try{JSONArray jobs=store.snapshot();for(int i=0;i<jobs.length();i++){JSONObject j=jobs.getJSONObject(i);if("waiting".equals(j.optString("status")))store.change(j.getString("id"),v->v.put("nextAttemptAt",0));}changed();}catch(Exception ignored){}});}catch(RejectedExecutionException ignored){}}};connectivity.registerDefaultNetworkCallback(network);}catch(Exception e){notifications.notify(NOTICE,notice(UploadQueueService.message(e),0,0,true));stopSelf();}}
  @Override public int onStartCommand(Intent intent,int flags,int id){startForeground(NOTICE,notice("正在处理后台保存…",0,0,false));if(store==null)return START_NOT_STICKY;lastStart=id;pending.incrementAndGet();String action=intent==null?WAKE:intent.getAction();long captured=intakeEpoch;if(ENQUEUE.equals(action))getSharedPreferences("incoming-status",MODE_PRIVATE).edit().putString("message","正在核对设备并加入保存队列…").apply();(ENQUEUE.equals(action)?intake:commands).execute(()->{try{if(ENQUEUE.equals(action))enqueue(intent,captured);else if(PAUSE.equals(action)||RESUME.equals(action)||CANCEL.equals(action))command(action,intent.getStringExtra("id"));}catch(Exception e){if(ENQUEUE.equals(action))getSharedPreferences("incoming-status",MODE_PRIVATE).edit().putString("message",UploadQueueService.message(e)).apply();notifications.notify(NOTICE,notice(UploadQueueService.message(e),0,0,true));}finally{pending.decrementAndGet();changed();}});return START_STICKY;}
  private synchronized void changed(){revision++;synchronized(signal){signal.notifyAll();}if(worker==null&&!destroyed){worker=new Thread(this::runQueue,"relay-background-save");worker.start();}}
  static ShareConnectionStore.Entry trusted(Context context,String serverId,String fingerprint)throws Exception{ShareConnectionStore.Entry local=ShareConnectionStore.local(),entry=local!=null&&local.serverId.equals(serverId)?local:new ShareConnectionStore(context).findId(serverId);if(entry==null||!entry.fingerprint.equals(fingerprint))throw new javax.net.ssl.SSLPeerUnverifiedException("可信设备已移除或身份已变化，请重新核对后添加保存任务。");if(entry.origin.startsWith("http://")&&!ShareConnectionStore.ownLoopback(entry.origin))throw new SaveFailure("本机文件池未开启，请先开启后恢复保存。");return entry;}
  static String[] parseIds(String value)throws IOException{if(value==null||value.length()>4000)throw new IOException("保存文件列表无效。");LinkedHashSet<String> ids=new LinkedHashSet<>();for(String id:value.split(",",-1)){if(!id.matches("[a-fA-F0-9-]{36}"))throw new IOException("保存文件编号无效。");ids.add(id);}if(ids.isEmpty()||ids.size()>100)throw new IOException("每批最多保存100个文件。");return ids.toArray(new String[0]);}
  static JSONObject visibleFile(JSONObject state,String id)throws Exception{JSONArray files=state.getJSONArray("files");for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);if(id.equals(f.optString("id"))){long size=f.getLong("size");if(size<0||size>MAX_FILE||!f.getString("sha256").matches("[a-f0-9]{64}"))throw new SaveFailure("原件的长度或完整性记录无效。");return f;}}throw new SaveFailure("文件已移走、删除或当前设备无权访问，请刷新文件池。");}
  private void enqueue(Intent intent,long captured)throws Exception{
    boolean wholeFolder=intent.getBooleanExtra("wholeFolder",false);String[] ids=wholeFolder?new String[0]:parseIds(intent.getStringExtra("ids"));ShareConnectionStore.Entry e=trusted(this,intent.getStringExtra("serverId"),intent.getStringExtra("fingerprint"));e=TrustedDiscovery.verifyOrReconnect(this,e);Uri tree=Uri.parse(intent.getStringExtra("tree"));if(!"content".equals(tree.getScheme())||!DocumentsContract.isTreeUri(tree))throw new SaveFailure("请重新授权目标文件夹。");
    boolean permitted=false;for(UriPermission p:getContentResolver().getPersistedUriPermissions())if(p.getUri().equals(tree)&&p.isReadPermission()&&p.isWritePermission())permitted=true;if(!permitted)throw new SaveFailure("目标文件夹读写授权未保留，请重新选择。");
    JSONObject state=new ShareTransport(e).request("/api/state","GET",null);ShareDirectorySupport.verifyIdentity(state,e);if(intent.getStringExtra("deviceId")==null||!intent.getStringExtra("deviceId").equals(state.getJSONObject("device").getString("id")))throw new SaveFailure("配对身份已改变，请重新选择文件并确认保存。");JSONArray incoming=new JSONArray();String batch=UUID.randomUUID().toString();for(String id:ids){JSONObject f=visibleFile(state,id);incoming.put(new JSONObject().put("id",UUID.randomUUID().toString()).put("batchId",batch).put("fileId",id).put("serverId",e.serverId).put("fingerprint",e.fingerprint).put("deviceId",state.getJSONObject("device").getString("id")).put("source",e.label).put("tree",tree.toString()).put("name",f.getString("name")).put("size",f.getLong("size")).put("sha256",f.getString("sha256")).put("status","queued").put("offset",0).put("createdAt",System.currentTimeMillis()).put("attempts",0));}if(wholeFolder){JSONArray plan=DirectorySavePlan.create(state,intent.getStringExtra("folderId"));for(int i=0;i<plan.length();i++){JSONObject j=plan.getJSONObject(i);j.put("batchId",batch).put("serverId",e.serverId).put("fingerprint",e.fingerprint).put("deviceId",state.getJSONObject("device").getString("id")).put("source",e.label).put("tree",tree.toString()).put("status","queued").put("offset",0).put("createdAt",System.currentTimeMillis()).put("attempts",0);incoming.put(j);}}synchronized(this){if(destroyed||captured!=intakeEpoch)throw new SaveFailure("整批保存已取消。");if(pauseIntake)for(int i=0;i<incoming.length();i++)incoming.getJSONObject(i).put("status","paused");store.add(incoming);getSharedPreferences("incoming-status",MODE_PRIVATE).edit().remove("message").apply();}
  }
  private void command(String action,String only)throws Exception{if(only==null)synchronized(this){if(CANCEL.equals(action))intakeEpoch++;if(PAUSE.equals(action))pauseIntake=true;if(RESUME.equals(action))pauseIntake=false;}JSONArray jobs=store.snapshot();for(int i=0;i<jobs.length();i++){JSONObject j=jobs.getJSONObject(i);String id=j.getString("id");if(only!=null&&!only.equals(id)||ReceiveQueueStore.terminal(j.optString("status")))continue;store.change(id,v->{String status=v.optString("status");if(ReceiveQueueStore.terminal(status))return;if(CANCEL.equals(action))v.put("status","cancelled");else if(PAUSE.equals(action)&&!"blocked".equals(status))v.put("status","paused");else if(RESUME.equals(action)&&!"blocked".equals(status))v.put("status","queued").put("nextAttemptAt",0).remove("error");});if(id.equals(currentId)&&!RESUME.equals(action))disconnect();else if(CANCEL.equals(action))cleanupCancelled(store.find(id));}synchronized(signal){signal.notifyAll();}}
  private void runQueue(){try{while(!destroyed){long seen=revision;JSONObject selected=null;long next=System.currentTimeMillis()+300000;boolean waiting=false;JSONArray jobs=store.snapshot();for(int i=0;i<jobs.length();i++){JSONObject j=jobs.getJSONObject(i);String s=j.optString("status");if("cancelled".equals(s)){cleanupCancelled(j);continue;}if("queued".equals(s)||"waiting".equals(s)){waiting=true;next=Math.min(next,j.optLong("nextAttemptAt"));if(j.optLong("nextAttemptAt")<=System.currentTimeMillis()){selected=j;break;}}}
      if(selected==null){if(wake!=null&&wake.isHeld())wake.release();if(waiting||pending.get()>0){notifications.notify(NOTICE,notice("等待网络或中转站恢复，缓存保留并自动重试",0,0,false));synchronized(signal){if(seen==revision)signal.wait(pending.get()>0?100:Math.max(100,Math.min(300000,next-System.currentTimeMillis())));}continue;}store.trim();notifications.notify(NOTICE,notice("保存队列已处理，点击查看结果、打开或分享",0,0,true));int idle=lastStart;synchronized(this){if(pending.get()>0||seen!=revision)continue;worker=null;}new Handler(Looper.getMainLooper()).post(()->{synchronized(ReceiveQueueService.this){if(worker==null&&pending.get()==0&&idle==lastStart){if(stopSelfResult(idle))stopForeground(false);}}});return;}
      currentId=selected.getString("id");if(wake!=null&&!wake.isHeld())wake.acquire(6*60*60*1000L);boolean locked=false;try{NativeStorageGate.beginSave();locked=true;save(selected);}catch(Exception e){failure(selected,e);}finally{disconnect();transport=null;connection=null;if(locked)NativeStorageGate.endSave();JSONObject latest=store.find(currentId);if("cancelled".equals(latest.optString("status")))cleanupCancelled(latest);currentId=null;}
    }}catch(Exception e){notifications.notify(NOTICE,notice(UploadQueueService.message(e),0,0,true));stopSelf();}finally{synchronized(this){if(worker==Thread.currentThread())worker=null;}}}
  private void check(String id)throws IOException{try{if(destroyed||!"saving".equals(store.find(id).optString("status")))throw new IOException("任务已暂停或取消。");}catch(IOException e){throw e;}catch(Exception e){throw new IOException(e);}}
  private void save(JSONObject job)throws Exception{
    String id=job.getString("id");store.change(id,j->{if(!"queued".equals(j.optString("status"))&&!"waiting".equals(j.optString("status")))throw new IOException("任务已暂停。");j.put("status","saving").remove("error");});check(id);
    ShareConnectionStore.Entry entry=TrustedDiscovery.verifyOrReconnect(this,trusted(this,job.getString("serverId"),job.getString("fingerprint")));ShareTransport api=new ShareTransport(entry);transport=api;JSONObject liveState=api.request("/api/state","GET",null);ShareDirectorySupport.verifyIdentity(liveState,entry);if(job.has("deviceId")&&!job.getString("deviceId").equals(liveState.getJSONObject("device").getString("id")))throw new SaveFailure("配对设备身份已改变，请重新添加保存任务。");if("folder".equals(job.optString("kind"))){saveFolder(job,liveState);return;}JSONObject file=visibleFile(liveState,job.getString("fileId"));long size=job.getLong("size");String sha=job.getString("sha256");if(size!=file.getLong("size")||!sha.equals(file.getString("sha256")))throw new SaveFailure("原件内容已改变，已保留缓存并阻止覆盖，请重新添加保存任务。");
    check(id);File part=store.payload(id);FileIntegrity.Value expected=new FileIntegrity.Value(size,hex(sha));
    // An interrupted publication is reconciled from actual bytes; never overwrite that document.
    if(job.has("destinationUri")){Uri output=Uri.parse(job.getString("destinationUri"));try(InputStream in=getContentResolver().openInputStream(output)){if(in==null)throw new IOException();FileIntegrity.require(FileIntegrity.read(in,size,()->check(id)),expected);finish(id,output,job.optString("savedName",job.getString("name")));return;}catch(FileIntegrity.Mismatch|FileNotFoundException incomplete){removeCreated(job,output);}}
    if(part.length()>size&&!part.delete())throw new SaveFailure("无法清理长度异常的保存缓存。");if(size-part.length()>store.directory.getUsableSpace()-RESERVE)throw new SaveFailure("手机空间不足以暂存并校验原件，请释放空间后恢复。");
    if(!part.isFile()||part.length()!=size){String route=api.request("/api/files/"+job.getString("fileId")+"/ticket","POST",new JSONObject().put("purpose","download")).getString("url");if(!route.matches("/api/files/"+job.getString("fileId")+"/content\\?ticket=[A-Za-z0-9_-]{43}"))throw new SaveFailure("中转站返回的下载地址无效。");long offset=part.length();HttpURLConnection c=entry.origin.startsWith("https://")?TlsIdentity.connect(entry.origin+route,entry.fingerprint):(HttpURLConnection)new URL(entry.origin+route).openConnection();connection=c;c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setInstanceFollowRedirects(false);c.setRequestProperty("Accept-Encoding","identity");if(offset>0){c.setRequestProperty("Range","bytes="+offset+"-");c.setRequestProperty("If-Range","\""+sha+"\"");}int code=c.getResponseCode();if(code!=200&&code!=206)throw new ShareTransport.ApiFailure(code,"",code==401||code==403?"连接授权已失效，请重新配对后添加保存任务。":"无法下载原件，请稍后重试。");if(!MessageDigest.isEqual(FileIntegrity.parseEtag(c.getHeaderField("ETag")),hex(sha)))throw new SaveFailure("下载原件哈希记录不一致，已阻止保存。");if(code==200)offset=0;else if(offset<=0||!("bytes "+offset+"-"+(size-1)+"/"+size).equals(c.getHeaderField("Content-Range")))throw new SaveFailure("下载续传范围不一致。");if(c.getContentLengthLong()!=size-offset)throw new SaveFailure("下载长度不一致，已阻止保存。");
      try(InputStream in=c.getInputStream();RandomAccessFile out=new RandomAccessFile(part,"rw")){if(offset==0)out.setLength(0);out.seek(offset);byte[] b=new byte[65536];int n;long count=offset;while((n=in.read(b))!=-1){check(id);trusted(this,job.getString("serverId"),job.getString("fingerprint"));if(n>size-count||store.directory.getUsableSpace()<RESERVE+n)throw new SaveFailure("原件长度异常或手机剩余空间不足。");out.write(b,0,n);count+=n;progress(id,"后台保存："+job.getString("name"),count,size);}out.getFD().sync();if(count!=size)throw new IOException("连接中断，已保留下载断点。");}finally{c.disconnect();connection=null;}}
    check(id);progress(id,"核验原件："+job.getString("name"),size,size);try(InputStream in=new FileInputStream(part)){FileIntegrity.require(FileIntegrity.read(in,size,()->check(id)),expected);}catch(FileIntegrity.Mismatch bad){if(!part.delete())throw new SaveFailure("原件校验失败，缓存无法清理，请取消任务。");throw new SaveFailure("原件校验失败，未保存到所选位置；恢复任务会重新下载。");}
    // Renew authorization immediately before publishing a fully downloaded copy.
    trusted(this,job.getString("serverId"),job.getString("fingerprint"));JSONObject publishState=api.request("/api/state","GET",null);ShareDirectorySupport.verifyIdentity(publishState,entry);if(job.has("deviceId")&&!job.getString("deviceId").equals(publishState.getJSONObject("device").getString("id")))throw new SaveFailure("配对身份已改变，已停止保存。");visibleFile(publishState,job.getString("fileId"));check(id);Uri tree=Uri.parse(job.getString("tree")),destination=DirectorySavePlan.unique(this,tree,parentFor(job),job.optString("outputName",job.getString("name")),false);String savedName=name(destination,job.getString("name"));try{store.change(id,j->j.put("destinationUri",destination.toString()).put("savedName",savedName));}catch(Exception error){throw new SaveFailure("目标文件已创建，但保存日志无法确认。已保留目标文件与缓存，请重启应用检查："+savedName);}
    try(SafDocumentCleanup cleanup=new SafDocumentCleanup(getContentResolver(),destination)){
      try{try(InputStream in=new FileInputStream(part);OutputStream out=cleanup.open("wt")){byte[] b=new byte[65536];int n;long count=0;while((n=in.read(b))!=-1){check(id);out.write(b,0,n);count+=n;progress(id,"写入所选目录："+savedName,count,size);}out.flush();}check(id);progress(id,"读回校验："+savedName,size,size);cleanup.verifySaved(expected,()->check(id));check(id);finish(id,destination,savedName);}
      catch(Exception error){
        // If journal readback became uncertain, find() throws and no published bytes are removed.
        JSONObject latest=store.find(id);if(!"done".equals(latest.optString("status"))){
          if(cleanup.deleteIncomplete())store.change(id,j->{j.remove("destinationUri");j.remove("cleanupUri");});
          else {store.change(id,j->j.put("cleanupUri",destination.toString()));throw new SaveFailure("未完成文件无法安全清理，请到保存目录删除："+savedName);}
        }
        if(error instanceof IOException&&"saving".equals(latest.optString("status")))throw new SaveFailure(UploadQueueService.message(error));throw error;
      }
    }
  }

  private void finish(String id,Uri uri,String name)throws Exception{store.change(id,j->{if(!"saving".equals(j.optString("status")))throw new IOException("保存已暂停。");j.put("status","done").put("destinationUri",uri.toString()).put("savedName",name).put("offset",j.getLong("size")).put("completedAt",System.currentTimeMillis()).remove("error");});try{SavedCopies.remember(this,store.find(id));}catch(Exception ignored){}store.payload(id).delete();}
  private Uri parentFor(JSONObject job)throws Exception {Uri tree=Uri.parse(job.getString("tree"));if(job.isNull("parentJobId")||!job.has("parentJobId"))return SafTreeFiles.root(tree);JSONObject parent=store.find(job.getString("parentJobId"));if(!job.getString("batchId").equals(parent.optString("batchId"))||!"folder".equals(parent.optString("kind"))||!"done".equals(parent.optString("status"))||!parent.has("destinationUri"))throw new SaveFailure("父目录尚未建立，请恢复整批保存或处理前面的目录任务。");Uri result=Uri.parse(parent.getString("destinationUri"));if(!"content".equals(result.getScheme())||!tree.getAuthority().equals(result.getAuthority())||!DocumentsContract.getTreeDocumentId(tree).equals(DocumentsContract.getTreeDocumentId(result)))throw new SaveFailure("保存目录授权范围不一致。");return result;}
  private void saveFolder(JSONObject job,JSONObject state)throws Exception {String id=job.getString("id"),folder=job.isNull("sourceFolderId")?null:job.optString("sourceFolderId");ShareDirectorySupport.Snapshot snapshot=new ShareDirectorySupport.Snapshot(state);if(!snapshot.get(folder).path.equals(job.getString("sourceFolderPath")))throw new SaveFailure("来源目录已移动或重命名，请重新添加整目录保存。");check(id);Uri tree=Uri.parse(job.getString("tree")),output=job.has("destinationUri")?Uri.parse(job.getString("destinationUri")):DirectorySavePlan.unique(this,tree,parentFor(job),job.getString("name"),true);if(!job.has("destinationUri"))store.change(id,j->j.put("destinationUri",output.toString()));try(Cursor cursor=getContentResolver().query(output,new String[]{DocumentsContract.Document.COLUMN_MIME_TYPE},null,null,null)){if(cursor==null||!cursor.moveToFirst()||!DocumentsContract.Document.MIME_TYPE_DIR.equals(cursor.getString(0)))throw new SaveFailure("目标目录已失效，请重新保存。");}check(id);store.change(id,j->j.put("status","done").put("savedName",name(output,job.optString("name"))).put("completedAt",System.currentTimeMillis()).remove("error"));}
  private void removeCreated(JSONObject job,Uri uri)throws Exception{try{if(!DocumentsContract.deleteDocument(getContentResolver(),uri))throw new IOException();}catch(Exception e){store.change(job.getString("id"),j->j.put("cleanupUri",uri.toString()));throw new SaveFailure("未完成文件无法清理，请在所选目录删除："+job.optString("savedName",job.optString("name")));}store.change(job.getString("id"),j->{j.remove("destinationUri");j.remove("cleanupUri");});}
  private void cleanupCancelled(JSONObject job)throws Exception{if(job.has("destinationUri")&&!"folder".equals(job.optString("kind"))){try{removeCreated(job,Uri.parse(job.getString("destinationUri")));}catch(Exception error){store.change(job.getString("id"),j->j.put("error",UploadQueueService.message(error)));}}store.payload(job.getString("id")).delete();}
  private Uri createUnique(Uri tree,String raw)throws Exception{Uri root=SafTreeFiles.root(tree),children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,DocumentsContract.getDocumentId(root));Set<String> names=new HashSet<>(),ids=new HashSet<>();try(Cursor c=getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME},null,null,null)){if(c==null)throw new SaveFailure("无法读取目标文件夹，已停止以防覆盖同名文件。");while(c.moveToNext()){if(ids.size()>50000)throw new SaveFailure("目标文件夹项目过多，请选择另一个目录。");ids.add(c.getString(0));names.add(c.getString(1).toLowerCase(Locale.ROOT));}}
    String base=PoolBackup.safeName(raw),candidate=base;int dot=base.lastIndexOf('.');if(dot<=0)dot=base.length();for(int n=2;names.contains(candidate.toLowerCase(Locale.ROOT));n++)candidate=base.substring(0,dot)+" ("+n+")"+base.substring(dot);Uri output=DocumentsContract.createDocument(getContentResolver(),root,"application/octet-stream",candidate);if(output==null||ids.contains(DocumentsContract.getDocumentId(output)))throw new SaveFailure("目标位置未创建独立新文件，已拒绝写入以保护旧文件。");return output;
  }
  private String name(Uri uri,String fallback){try(Cursor c=getContentResolver().query(uri,new String[]{DocumentsContract.Document.COLUMN_DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())return c.getString(0);}catch(Exception ignored){}return fallback;}
  private static byte[] hex(String value){byte[] b=new byte[32];for(int i=0;i<b.length;i++)b[i]=(byte)Integer.parseInt(value.substring(i*2,i*2+2),16);return b;}
  private void failure(JSONObject original,Exception error)throws Exception{String id=original.getString("id");JSONObject latest=store.find(id);String status=latest.optString("status");if("paused".equals(status)||"cancelled".equals(status)||"done".equals(status))return;boolean identity=error instanceof SSLException, retry=error instanceof IOException&&!identity&&!(error instanceof SaveFailure)&&!(error instanceof SecurityException);if(error instanceof ShareTransport.ApiFailure){int code=((ShareTransport.ApiFailure)error).status;retry=code==408||code==429||code>=500;}final boolean again=retry;store.change(id,j->{if(!"saving".equals(j.optString("status"))&&!"queued".equals(j.optString("status")))return;int attempts=j.optInt("attempts")+1;j.put("status",identity?"blocked":again?"waiting":"failed").put("error",UploadQueueService.message(error)).put("attempts",attempts).put("nextAttemptAt",System.currentTimeMillis()+Math.min(300000L,2000L*(1L<<Math.min(7,attempts))));});}
  private void progress(String id,String text,long count,long total){long now=System.currentTimeMillis();if(now-notified>350){notified=now;notifications.notify(NOTICE,notice(text,count,total,false));}if(now-journaled>1000){journaled=now;try{store.change(id,j->j.put("offset",count));}catch(Exception ignored){}}}
  private Notification notice(String text,long count,long total,boolean idle){PendingIntent open=PendingIntent.getActivity(this,34,new Intent(this,ReceiveQueueActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification.Builder b=new Notification.Builder(this,"relay-saves").setSmallIcon(R.drawable.ic_relay).setContentTitle(idle?"星月夜保存结果":"星月夜正在后台保存").setContentText(text).setStyle(new Notification.BigTextStyle().bigText(text)).setContentIntent(open).setOnlyAlertOnce(true).setOngoing(!idle);if(!idle)b.setProgress(100,total>0?(int)Math.min(100,count*100/total):0,total<=0);for(String action:new String[]{idle?RESUME:PAUSE})b.addAction(new Notification.Action.Builder(null,idle?"恢复保存":"暂停保存",PendingIntent.getForegroundService(this,action.hashCode()+34,new Intent(this,ReceiveQueueService.class).setAction(action),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT)).build());return b.build();}
  private void disconnect(){HttpURLConnection c=connection;if(c!=null)new Thread(c::disconnect,"relay-save-disconnect").start();ShareTransport t=transport;if(t!=null)t.cancel();}
  @Override public void onTimeout(int id,int type){try{commands.execute(()->{try{command(PAUSE,null);}catch(Exception ignored){}stopSelf();});}catch(Exception ignored){stopSelf();}}
  @Override public IBinder onBind(Intent i){return null;}
  @Override public void onDestroy(){destroyed=true;disconnect();synchronized(signal){signal.notifyAll();}try{if(connectivity!=null&&network!=null)connectivity.unregisterNetworkCallback(network);}catch(Exception ignored){}if(wake!=null&&wake.isHeld())wake.release();commands.shutdown();intake.shutdown();super.onDestroy();}
}
